p=R/'pages/149_scan014.tex';s=p.read_text();assert '$\\Gamma$ réduite' in s;s=s.replace('$\\Gamma$ réduite',r'$\Gamma$ \unsure{réduite|réduit}');p.write_text(s)
p=R/'reviews/149_scan014.json';r=json.loads(p.read_text());b=next(x for x in r['audit_boxes'] if x['box']=='b16');coords=[b[k] for k in ('x0','y0','x1','y1')]
r['changes'].append({'id':'audit_b16_ending','place':'Revenant paragraph, word after image dans Gamma','C':'réduite','H':'réduite','final':r'\unsure{réduite|réduit}','evidence':ch['b16']['evidence'],'crop':'crops/149_scan014_second_b16.png','box':coords,'confidence':'low','against_C':True,'against_H':True,'kind':'misread word','error_category':'Words','marked_in_H':False,'mathematical':False})
r['doubts'].append({'place':'Revenant paragraph, word after image dans Gamma','reading':r'\unsure{réduite|réduit}','alternatives':['réduite','réduit'],'confidence':'low','reason':ch['b16']['evidence']})
r['notes'].append('Independent audit: all15 differing boxes and64 token spans were personally inspected. Only the compressed ending réduite/réduit changes, now explicitly doubtful. Est, the pair (1,tau), subscript zero in the opening corollary, the literal sur and the separate foliation hand are retained. The rounded Z and script-E/epsilon ambiguities remain explicit; lowercase pi follows the already inspected kernel forms. No mathematical claim was newly checked during this reading audit.')
